private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int nextCharIndex = i;
    while (i < bb.limit() && bb.get(i) >= 0) {
        int octet = bb.get(i);
        if (octet < 128) {
            sb.append((char) octet);
            nextCharIndex++;
        } else if (octet < 192) {
            throw new IllegalArgumentException("Invalid UTF-8 sequence at index " + i);
        } else if (octet < 224) {
            int secondOctet = bb.get(i + 1);
            if (secondOctet < 128 || secondOctet > 191) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence at index " + i);
            }
            sb.append((char) ((octet & 0x1F) << 6 | (secondOctet & 0x3F)));
            nextCharIndex += 2;
        } else if (octet < 240) {
            int secondOctet = bb.get(i + 1);
            int thirdOctet = bb.get(i + 2);
            if (secondOctet < 128 || secondOctet > 191 || thirdOctet < 128 || thirdOctet > 191) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence at index " + i);
            }
            sb.append((char) ((octet & 0x0F) << 12 | (secondOctet & 0x3F) << 6 | (thirdOctet & 0x3F)));
            nextCharIndex += 3;
        } else if (octet < 248) {
            int secondOctet = bb.get(i + 1);
            int thirdOctet = bb.get(i + 2);
            int fourthOctet = bb.get(i + 3);
            if (secondOctet < 128 || secondOctet > 191 || thirdOctet < 128 || thirdOctet > 191 || fourthOctet < 128 || fourthOctet > 191) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence at index " + i);
            }
            sb.append((char) ((octet & 0x07) << 18 | (secondOctet & 0x3F) << 12 | (thirdOctet & 0x3F) << 6 | (fourthOctet & 0x3F)));
            nextCharIndex += 4;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 sequence at index " + i);
        }
        i++;
    }
    return nextCharIndex;
}

