private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Check if the start and stop nodes are valid
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes cannot be null");
    }

    // Initialize the circulator
    OuterFaceCirculator circulator = new OuterFaceCirculator();

    // Traverse the graph in the specified direction
    Node current = start;
    while (current != null) {
        // Check if the current node satisfies the predicate
        if (predicate.test(current)) {
            circulator.setNode(current);
            return circulator;
        }

        // Move to the next node in the specified direction
        current = getNextNode(current, dir);
    }

    // If no node satisfies the predicate, return the stop node
    circulator.setNode(stop);
    return circulator;
}

private Node getNextNode(Node current, int dir) {
    switch (dir) {
        case 0: // Left
            return current.getLeft();
        case 1: // Right
            return current.getRight();
        case 2: // Up
            return current.getUp();
        case 3: // Down
            return current.getDown();
        default:
            throw new IllegalArgumentException("Invalid direction");
    }
}

