private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Graph and vertices cannot be null or empty");
    }

    int n = vertices.size();
    if (n <= 1) {
        return true; // A graph with 0 or 1 vertex is always a clique
    }

    for (V v : vertices) {
        Set<E> neighbors = graph.neighbors(v);
        if (neighbors.size() < n - 1) {
            return false; // If any vertex has fewer than n-1 neighbors, it's not a clique
        }
    }

    return true; // All vertices have n-1 neighbors, so it's a clique
}

