public int readTag() throws IOException {
    // Read the next byte
    int byteValue = inputStream.read();
    if (byteValue == -1) {
        // End of file reached
        return 0;
    }
    // Extract the tag number from the byte
    int tag = (byteValue & 0x7F) << 3;
    // Check if the next byte is a valid length prefix
    if ((byteValue & 0x80) != 0) {
        // Read the length prefix
        int lengthPrefix = inputStream.read();
        if (lengthPrefix == -1) {
            // End of file reached
            return 0;
        }
        // Calculate the total length of the field
        int totalLength = (lengthPrefix & 0x7F) << 3;
        // Read the field data
        byte[] fieldData = new byte[totalLength];
        inputStream.read(fieldData);
        // Return the tag number
        return tag;
    }
    // Return the tag number
    return tag;
}

